        public static string Clean(Pet p){return p.SpeciesId<0?"깨끗해졌어! 고마워!":clean[p.SpeciesId];}
        public static string Greet(Pet p){return p.SpeciesId<0?"안녕! 같이 놀자!":greetings[p.SpeciesId];}
        public static string Need(Pet p) {
            string need=p.Illness>20?"치료":p.Hunger>60?"물":p.Fatigue>75?"휴식":null;
            if(need==null)return null;
            if(p.SpeciesId<0)return need=="치료"?"조금 아파… 도와줘.":need=="물"?"목말라! 물 마시고 싶어.":"졸려… 집에서 잘래.";
            string[] requests={"혹시 "+need+" 부탁해도 될까…?",need+" 하고 네 옆에서 쉬고 싶어~",need+" 좀 필요해. 너한테 부탁하는 건 아니고.","괜찮다면 "+need+" 도와줄래?","지금은 "+need+"부터 해볼까?","다른 애보다 나 먼저 "+need+" 챙겨줘.",need+"… 움직이기 전에 좀 도와줘.","조용히 "+need+" 도와주면 좋겠어.",need+" 하고 다시 힘내자!","지금 "+need+" 필요하다니까!","짐에게 "+need+"를 준비하라!","마법으로도 "+need+"는 대신할 수 없겠군.","항해 전 "+need+"부터 챙겨야겠군.",need+"는 미루면 안 돼. 너도 기억해.",need+" 없이는 붓을 들기 어렵겠어.","리듬이 흐트러졌어. "+need+"부터!","현재 필요한 건 "+need+"야. 책에도 나와.","다음 탐험 전에 "+need+"부터 하자.",need+" 필요. 지구의 지원을 요청한다.","다음 승부를 위해 "+need+"부터 해야겠어.","나한테도 "+need+" 챙겨줄 거지?","내 속도로 "+need+"하고 싶어.","장난은 잠깐! 지금은 "+need+" 필요해.",need+" 좀 해줄래? 특별히 부탁하는 거야.",need+" 필요해! 왜 놀라는 건데?!",need+" 도와줘… 조용히 부탁할게.",need+" 하고 나면 다시 연습할 거야.","지금 "+need+" 필요해. 숨길 일은 아니잖아.","다음 판 전에 "+need+"부터 챙기자.","지금은 "+need+"가 제일 필요해!",need+" 필요하구마. 평범한 고구마도 그렇구마!"};
            return requests[p.SpeciesId];
        }
        public static string Get(Pet p,int eventId){if(p.SpeciesId<0)return new[]{"맛있어! 더 자랄 수 있겠어.","이제 덜 아파. 고마워!","헤헤, 손이 따뜻해.","저건 뭐야? 같이 보러 가자!"}[eventId];return lines[p.SpeciesId][eventId];}
    }
